      (expo(2, 2*k) - expo(3, 2*k)) % 5;
      == (expo(4, k) - expo(9, k)) % 5;
      == (expo(-1, k) - expo(-1, k)) % 5;
      == 0 % 5;
      == 0;
    }
  }
}

method Main() {
  // Test expo function
  assert expo(2, 0) == 1;
  assert expo(2, 1) == 2;
  assert expo(2, 3) == 8;
  assert expo(3, 2) == 9;

  // Test the lemma for small even values
  var n: nat := 0;
  while n < 10
    invariant 0 <= n
  {
    if n % 2 == 0 {
      Expon23Even(n/2);
      assert (expo(2, n) - expo(3, n)) % 5 == 0;
    }
    n := n + 1;
  }

  // Test the new MainModProperty lemma
  var k: nat := 0;
  while k < 10
    invariant 0 <= k
  {
    MainModProperty(k);
    assert expo(4, k) % 5 == expo(9, k) % 5;
    k := k + 1;
  }

  print "All tests passed!\n";
}
